import React, { useCallback, useEffect, useRef, useState } from 'react';
import { X, Plus, RefreshCw, ArrowUp, FolderOpen, Upload, PanelBottom, Maximize, Settings2, Server, Folder, FileText, FileCode2, Link2, ChevronDown, ChevronUp, ChevronLeft, ChevronRight, Minus, Square } from 'lucide-react';
import { api, isPreview } from './api';
import TerminalView, { keyChord, mouseChord } from './TerminalView';
import type { AppEvent, AppSettings, FileEntry, FileListing, HostProfile, RemoteRequest, SessionInfo, TransferInfo, TransferRequest } from '../shared/types';

type Side = 'local' | 'remote';
type Elevation = { elevated?: boolean; sudoPassword?: string };
type Toast = { id: number; message: string; error?: boolean };
type SudoTask = { label: string; run: (elevation: Elevation) => Promise<unknown> };
type Context = { x: number; y: number; side: Side; entry: FileEntry };
const dragMime = 'application/x-gooeshell-files';
const appIcon = './gooeshell-icon.png';
const shortcutNames: Record<string, string> = { connect: '新建 SSH 连接', settings: '设置', files: '显示 / 隐藏文件管理', fullscreen: '无边框全屏', zen: '纯终端模式', copy: '复制选中文本', paste: '粘贴', search: '查找终端内容', fontUp: '增大字体', fontDown: '减小字体' };
const defaultSettings: AppSettings = { fontFamily: 'DejaVu Sans Mono', chineseFont: 'Microsoft YaHei', fontSize: 14, lineHeight: 1.15, cursorBlink: false, copyOnSelect: false, rightClickPaste: false, backgroundImage: '', backgroundOpacity: .15, shortcuts: { connect: 'Ctrl+Shift+N', settings: 'Ctrl+,', files: 'Ctrl+Shift+E', fullscreen: 'F11', zen: 'Ctrl+Shift+F11', copy: 'Ctrl+Shift+C', paste: 'Ctrl+Shift+V', search: 'Ctrl+Shift+F', fontUp: 'Ctrl+=', fontDown: 'Ctrl+-' } };
function keyCombo(e: KeyboardEvent | React.KeyboardEvent) { if (['Control', 'Shift', 'Alt', 'Meta'].includes(e.key)) return ''; return keyChord('nativeEvent' in e ? e.nativeEvent as KeyboardEvent : e); }
const mouseNames: Record<string, string> = { MouseMiddle: '中键单击', MouseRight: '右键单击', MouseBack: '后退侧键', MouseForward: '前进侧键' };
function shortcutLabel(value: string) { return value.split('+').map(part => mouseNames[part] || ({ Space: '空格', Enter: '回车', Backspace: '退格', Delete: '删除键', Escape: 'Esc', ArrowUp: '↑', ArrowDown: '↓', ArrowLeft: '←', ArrowRight: '→' } as Record<string, string>)[part] || part).join(' + '); }
function shortcutImpact(value: string) { if (!value || /Mouse/.test(value) || /^F\d+$/.test(value)) return ''; if (!value.includes('+') || /^Shift\+[^+]+$/.test(value)) return '该按键在终端内会触发操作，不再输入原来的字符或执行原来的按键功能。'; if (/^Ctrl\+[A-Z]$/.test(value)) return '该组合键会优先触发这里的操作，可能覆盖 shell 或 tmux 的原有快捷键。'; return ''; }
function bytes(value: number) { if (!Number.isFinite(value) || value < 0) return '—'; if (value < 1024) return `${value} B`; const unit = Math.min(4, Math.floor(Math.log(value) / Math.log(1024))); return `${(value / 1024 ** unit).toFixed(value / 1024 ** unit < 10 ? 1 : 0)} ${['B', 'KB', 'MB', 'GB', 'TB'][unit]}`; }
function basename(path: string) { return path.replace(/[\\/]$/, '').split(/[\\/]/).pop() || path; }
function joinPath(base: string, leaf: string, side: Side) { const sep = side === 'local' && base.includes('\\') ? '\\' : '/'; return base.replace(/[\\/]$/, '') + sep + leaf; }
function parentPath(path: string, side: Side) { if (side === 'remote') return path.replace(/\/+$/, '').replace(/\/[^/]*$/, '') || '/'; const trimmed = path.replace(/[\\/]+$/, ''); const parent = trimmed.replace(/[\\/][^\\/]*$/, ''); return parent === trimmed || /^[A-Za-z]:$/.test(parent) ? (parent.match(/^[A-Za-z]:/)?.[0] || parent) + '\\' : parent; }
function errorText(error: unknown) { return error instanceof Error ? error.message : String(error); }
function transferErrorMessage(message: string) { return /PERMISSION_DENIED|permission denied|权限不足/i.test(message) ? '文件传输权限不足。当前不支持 sudo 文件传输，请选择当前账号有权限的源文件和目标目录后重新传输。' : message; }
function modeText(mode?: number) { if (mode === undefined) return '—'; return [0o400, 0o200, 0o100, 0o40, 0o20, 0o10, 0o4, 0o2, 0o1].map((bit, i) => mode & bit ? 'rwx'[i % 3] : '-').join(''); }
function sorted(entries: FileEntry[]) { return [...entries].sort((a, b) => Number(b.type === 'directory') - Number(a.type === 'directory') || a.name.localeCompare(b.name, 'zh-CN', { numeric: true })); }
function IconButton({ children, title, onClick, disabled, active }: { children: React.ReactNode; title: string; onClick?: () => void; disabled?: boolean; active?: boolean }) { const icons: Record<string, typeof X> = { '×': X, '+': Plus, '↻': RefreshCw, '↑': ArrowUp, '…': FolderOpen, '⇧': Upload, '▥': PanelBottom, '⛶': Maximize, '⚙': Settings2 }; const Icon = typeof children === 'string' ? icons[children] : undefined; return <button type="button" className={`icon-button${active ? ' active' : ''}`} title={title} aria-label={title} onClick={onClick} disabled={disabled}>{Icon ? <Icon size={15} strokeWidth={1.7} /> : children}</button>; }
function Modal({ title, children, footer, close, wide, compact }: { title: string; children: React.ReactNode; footer?: React.ReactNode; close: () => void; wide?: boolean; compact?: boolean }) { const element = useRef<HTMLElement>(null); const closeRef = useRef(close); closeRef.current = close; useEffect(() => { const previous = document.activeElement as HTMLElement | null; const handle = (event: KeyboardEvent) => { const dialogs = document.querySelectorAll('[role="dialog"]'); if (dialogs[dialogs.length - 1] !== element.current) return; if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); closeRef.current(); } if (event.key === 'Tab') { const controls = [...(element.current?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [tabindex="0"]') || [])].filter(control => control.offsetParent !== null); const first = controls[0], last = controls.at(-1); if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); } } }; window.addEventListener('keydown', handle); if (!element.current?.contains(document.activeElement)) element.current?.querySelector<HTMLElement>('input, button')?.focus(); return () => { window.removeEventListener('keydown', handle); if (previous?.isConnected) previous.focus(); }; }, []); return <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) close(); }}><section ref={element} className={`modal${wide ? ' wide' : ''}${compact ? ' compact' : ''}`} role="dialog" aria-modal="true" aria-label={title}><div className="modal-header"><span className="modal-title">{title}</span><IconButton title="关闭" onClick={close}>×</IconButton></div>{children}{footer && <div className="modal-footer">{footer}</div>}</section></div>; }

function ConnectionDialog({ profile, busy, error, onSave, onConnect, close }: { profile?: HostProfile; busy: boolean; error: string; onSave: (profile: HostProfile) => Promise<void>; onConnect: (profile: HostProfile, password: string, passphrase: string) => Promise<void>; close: () => void }) {
  const [draft, setDraft] = useState<HostProfile>(profile || { id: crypto.randomUUID(), name: '', host: '', port: 22, username: 'root', auth: 'password', rememberHost: true, encoding: 'utf8' });
  const [password, setPassword] = useState(''); const [passphrase, setPassphrase] = useState(''); const [localError, setLocalError] = useState(''); const [saveBusy, setSaveBusy] = useState(false);
  const change = <K extends keyof HostProfile>(key: K, value: HostProfile[K]) => setDraft(prev => ({ ...prev, [key]: value }));
  const value = () => ({ ...draft, name: draft.name.trim() || draft.host.trim(), host: draft.host.trim().replace(/^\[|\]$/g, ''), username: draft.username.trim() });
  const valid = () => { if (!draft.host.trim() || !draft.username.trim()) { setLocalError('请填写服务器地址和用户名。'); return false; } if (!Number.isInteger(draft.port) || draft.port < 1 || draft.port > 65535) { setLocalError('端口应在 1–65535 之间。'); return false; } if (draft.auth === 'key' && !draft.privateKeyPath) { setLocalError('请选择本机私钥文件。'); return false; } setLocalError(''); return true; };
  return <Modal title={profile ? '连接服务器' : '新建 SSH 连接'} close={() => { if (!busy) close(); }} footer={<><span className="footer-note">密码与私钥口令不会保存</span><button className="button secondary" disabled={busy || saveBusy} onClick={async () => { if (!valid()) return; setSaveBusy(true); try { await onSave(value()); close(); } catch (e) { setLocalError(errorText(e)); } finally { setSaveBusy(false); } }}>仅保存</button><button className="button primary" disabled={busy || saveBusy} form="connect-form" type="submit">{busy ? <><span className="loading-spin" />正在连接…</> : '连接服务器'}</button></>}>
    <form id="connect-form" className="modal-body connection-form" onSubmit={e => { e.preventDefault(); if (valid()) void onConnect(value(), password, passphrase); }}>
      <div className="form-grid"><div className="form-field full"><label htmlFor="host-name">连接名称</label><input id="host-name" value={draft.name} onChange={e => change('name', e.target.value)} placeholder="例如：生产服务器" /></div><div className="form-field"><label htmlFor="host-address">服务器地址</label><input id="host-address" autoFocus value={draft.host} onChange={e => change('host', e.target.value)} placeholder="192.168.1.10 / example.com" autoComplete="off" /></div><div className="form-field"><label htmlFor="host-port">SSH 端口</label><input id="host-port" type="number" min={1} max={65535} value={draft.port} onChange={e => change('port', Number(e.target.value))} /></div><div className="form-field"><label htmlFor="host-user">用户名</label><input id="host-user" value={draft.username} onChange={e => change('username', e.target.value)} autoComplete="off" /></div><div className="form-field"><label htmlFor="host-encoding">终端编码</label><select id="host-encoding" value={draft.encoding} onChange={e => change('encoding', e.target.value as HostProfile['encoding'])}><option value="utf8">UTF-8（推荐）</option><option value="gb18030">GB18030 / GBK</option><option value="big5">Big5</option></select></div><div className="form-field full"><label>身份验证</label><div className="radio-group">{([['password', '密码'], ['key', '私钥文件'], ['agent', 'SSH Agent']] as const).map(([id, label]) => <button key={id} type="button" className={draft.auth === id ? 'active' : ''} onClick={() => change('auth', id)}>{label}</button>)}</div></div>
      {draft.auth === 'password' && <div className="form-field full"><label htmlFor="host-password">登录密码</label><input id="host-password" type="password" value={password} onChange={e => setPassword(e.target.value)} autoComplete="new-password" placeholder="仅用于本次连接，不写入配置" /></div>}
      {draft.auth === 'key' && <><div className="form-field full"><label htmlFor="host-key">私钥文件</label><div className="field-inline"><input id="host-key" value={draft.privateKeyPath || ''} onChange={e => change('privateKeyPath', e.target.value)} placeholder="例如 C:\Users\你\.ssh\id_ed25519" /><button type="button" className="button secondary" onClick={async () => { try { const [path] = await api.chooseFiles({ title: '选择 SSH 私钥' }); if (path) change('privateKeyPath', path); } catch (e) { setLocalError(errorText(e)); } }}>浏览…</button></div></div><div className="form-field full"><label htmlFor="key-passphrase">私钥口令（可选）</label><input id="key-passphrase" type="password" value={passphrase} onChange={e => setPassphrase(e.target.value)} autoComplete="new-password" placeholder="仅加密的私钥需要" /></div></>}
      {draft.auth === 'agent' && <div className="form-field full"><div className="hint">使用本机正在运行的 SSH Agent 中的密钥。</div></div>}
      <div className="form-field full"><label className="checkbox-row"><input type="checkbox" checked={draft.rememberHost} onChange={e => change('rememberHost', e.target.checked)} />允许保存服务器指纹（首次连接仍需确认）</label><span className="hint">关闭后可选择仅信任本次连接；密码始终不会保存。</span></div></div>
      {(error || localError) && <div className="form-error" role="alert">{localError || error}</div>}
    </form></Modal>;
}

function SettingsDialog({ settings, save, close }: { settings: AppSettings; save: (settings: AppSettings) => Promise<void>; close: () => void }) {
  const [draft, setDraft] = useState(settings); const [tab, setTab] = useState('font'); const [fonts, setFonts] = useState<string[]>(['DejaVu Sans Mono', 'Consolas', 'JetBrains Mono', 'Cascadia Mono', 'Microsoft YaHei', 'SimSun']); const [record, setRecord] = useState(''); const [error, setError] = useState(''); const [saving, setSaving] = useState(false);
  const [mouseEditor, setMouseEditor] = useState(''); const [mouseButton, setMouseButton] = useState('MouseMiddle'); const [mouseModifiers, setMouseModifiers] = useState<string[]>([]); const suppressCapturedMouse = useRef(false);
  const fontOptions = [...new Set([...fonts, draft.fontFamily, draft.chineseFont])].filter(Boolean).sort((a, b) => a.localeCompare(b));
  const change = <K extends keyof AppSettings>(key: K, value: AppSettings[K]) => setDraft(prev => ({ ...prev, [key]: value }));
  const assignShortcut = (id: string, combo: string) => { const conflict = Object.entries(draft.shortcuts).find(([otherId, value]) => otherId !== id && value.toLowerCase() === combo.toLowerCase()); if (conflict) { setError(`“${shortcutLabel(combo)}”已用于“${shortcutNames[conflict[0]] || conflict[0]}”，请换一个按键或先修改那一项。`); return false; } change('shortcuts', { ...draft.shortcuts, [id]: combo }); setRecord(''); setMouseEditor(''); setError(''); return true; };
  useEffect(() => { api.fonts().then(items => setFonts([...new Set([...fonts, ...items])].sort((a, b) => a.localeCompare(b)))).catch(() => {}); }, []);
  useEffect(() => { if (!record) return; const capture = (event: KeyboardEvent) => { if (event.isComposing) return; event.preventDefault(); event.stopImmediatePropagation(); if (event.key === 'Escape') { setRecord(''); return; } if (event.repeat) return; const combo = keyCombo(event); if (combo) assignShortcut(record, combo); }; const captureMouse = (event: MouseEvent) => { if (event.button === 0) return; const combo = mouseChord(event); if (!combo) return; event.preventDefault(); event.stopImmediatePropagation(); suppressCapturedMouse.current = true; assignShortcut(record, combo); }; window.addEventListener('keydown', capture, true); window.addEventListener('mousedown', captureMouse, true); return () => { window.removeEventListener('keydown', capture, true); window.removeEventListener('mousedown', captureMouse, true); }; }, [record, draft.shortcuts]);
  useEffect(() => { const suppress = (event: MouseEvent) => { if (suppressCapturedMouse.current) { event.preventDefault(); event.stopImmediatePropagation(); } }; const release = () => { if (suppressCapturedMouse.current) setTimeout(() => { suppressCapturedMouse.current = false; }, 0); }; window.addEventListener('contextmenu', suppress, true); window.addEventListener('auxclick', suppress, true); window.addEventListener('mouseup', release, true); return () => { window.removeEventListener('contextmenu', suppress, true); window.removeEventListener('auxclick', suppress, true); window.removeEventListener('mouseup', release, true); }; }, []);
  return <Modal title="设置" wide close={close} footer={<><span className="footer-note">设置保存在本机，可随时修改</span><button className="button secondary" onClick={close}>取消</button><button className="button primary" disabled={saving || !!record} onClick={async () => { setSaving(true); try { await save(draft); close(); } catch (e) { setError(errorText(e)); } finally { setSaving(false); } }}>保存设置</button></>}>
    <div className="settings-layout"><nav className="settings-tabs">{[['font', '字体与外观'], ['shortcuts', '快捷键'], ['terminal', '终端操作'], ['about', '关于']].map(([id, label]) => <button key={id} className={tab === id ? 'active' : ''} onClick={() => { setTab(id); setRecord(''); }}>{label}</button>)}</nav><div className="settings-content">
      {tab === 'font' && <><h3>终端字体</h3><div className="form-grid"><div className="form-field"><label htmlFor="font-en">英文字体</label><select id="font-en" value={draft.fontFamily} onChange={e => change('fontFamily', e.target.value)}>{fontOptions.map(font => <option key={font} value={font}>{font}</option>)}</select></div><div className="form-field"><label htmlFor="font-zh">中文字体</label><select id="font-zh" value={draft.chineseFont} onChange={e => change('chineseFont', e.target.value)}>{fontOptions.map(font => <option key={font} value={font}>{font}</option>)}</select></div><div className="form-field"><label htmlFor="font-size">字号 · {draft.fontSize} px</label><input id="font-size" type="range" min={9} max={30} step={1} value={draft.fontSize} onChange={e => change('fontSize', Number(e.target.value))} /></div><div className="form-field"><label htmlFor="line-height">行高 · {draft.lineHeight.toFixed(2)}</label><input id="line-height" type="range" min={1} max={1.8} step={.05} value={draft.lineHeight} onChange={e => change('lineHeight', Number(e.target.value))} /></div></div><div className="font-preview" style={{ fontFamily: `"${draft.fontFamily}", "${draft.chineseFont}", monospace`, fontSize: draft.fontSize, lineHeight: draft.lineHeight }}><span className="accent">root@server</span><span className="preview-muted">:~$ </span>ls -lah<br />0123456789 AaBbCc 终端中文字体预览<br /><span className="preview-muted">drwxr-xr-x　文档 / Documents</span></div><h3 style={{ marginTop: 23 }}>背景图片</h3><div className="field-inline"><input aria-label="背景图片路径" value={draft.backgroundImage} onChange={e => change('backgroundImage', e.target.value)} placeholder="留空使用纯黑背景" /><button className="button secondary" onClick={async () => { try { const [path] = await api.chooseFiles({ title: '选择终端背景图片' }); if (path) change('backgroundImage', path); } catch (e) { setError(errorText(e)); } }}>浏览…</button><button className="button secondary" onClick={() => change('backgroundImage', '')}>清除</button></div>{draft.backgroundImage && <div className="form-field" style={{ marginTop: 13 }}><label>图片不透明度 · {Math.round(draft.backgroundOpacity * 100)}%</label><input aria-label="图片不透明度" type="range" min={.02} max={.7} step={.01} value={draft.backgroundOpacity} onChange={e => change('backgroundOpacity', Number(e.target.value))} /></div>}</>}
      {tab === 'shortcuts' && <><h3>键盘与鼠标快捷操作</h3><p className="settings-description">点击触发方式，录入单个按键、组合键，或单击鼠标中键 / 右键 / 侧键。也可点“鼠标”直接选择按钮。每项操作使用一种触发方式。</p><div className="shortcut-presets"><button className="button small secondary" title="将粘贴的当前触发方式替换为鼠标中键单击" onClick={() => assignShortcut('paste', 'MouseMiddle')}>设为中键粘贴</button><span>替换当前粘贴快捷键；不会影响文件列表操作。</span></div><table className="shortcut-table"><thead><tr><th>操作</th><th style={{ textAlign: 'right' }}>触发方式</th></tr></thead><tbody>{Object.entries(shortcutNames).map(([id, name]) => <React.Fragment key={id}><tr><td>{name}</td><td><div className="shortcut-actions"><button type="button" aria-label={`录入${name}快捷方式`} className={`shortcut-record${record === id ? ' recording' : ''}`} onClick={() => { setRecord(id); setMouseEditor(''); setError(''); }}>{record === id ? '按键或单击鼠标…' : shortcutLabel(draft.shortcuts[id] || '') || '未设置'}</button><button type="button" className={`shortcut-mouse-button${mouseEditor === id ? ' active' : ''}`} aria-label={`选择${name}的鼠标按钮`} onClick={() => { const current = (draft.shortcuts[id] || '').split('+'); setRecord(''); setMouseEditor(mouseEditor === id ? '' : id); setMouseButton(current.find(part => mouseNames[part]) || 'MouseMiddle'); setMouseModifiers(current.filter(part => ['Ctrl', 'Alt', 'Shift'].includes(part))); setError(''); }}>鼠标</button></div></td></tr>{record === id && <tr className="shortcut-detail-row"><td colSpan={2}><div className="shortcut-capture-hint"><span>正在录入“{name}”；Esc 取消，左键保留用于操作界面。</span><button type="button" className="text-button" onClick={() => setRecord('')}>取消录入</button></div></td></tr>}{mouseEditor === id && <tr className="shortcut-detail-row"><td colSpan={2}><div className="mouse-binding-editor"><label>鼠标按钮<select aria-label={`${name}鼠标按钮`} value={mouseButton} onChange={e => setMouseButton(e.target.value)}>{Object.entries(mouseNames).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><div className="mouse-binding-modifiers"><span>同时按住（可选）</span><div>{['Ctrl', 'Alt', 'Shift'].map(modifier => <label key={modifier}><input type="checkbox" checked={mouseModifiers.includes(modifier)} onChange={e => setMouseModifiers(previous => e.target.checked ? [...previous, modifier] : previous.filter(item => item !== modifier))} />{modifier}</label>)}</div></div><button type="button" className="button small primary" onClick={() => assignShortcut(id, [...['Ctrl', 'Alt', 'Shift'].filter(modifier => mouseModifiers.includes(modifier)), mouseButton].join('+'))}>应用</button></div></td></tr>}</React.Fragment>)}</tbody></table>{Object.entries(draft.shortcuts).filter(([, value]) => shortcutImpact(value)).map(([id, value]) => <div className="shortcut-impact" key={id}><strong>{shortcutNames[id] || id} · {shortcutLabel(value)}</strong><span>{shortcutImpact(value)} 保留此设置即可采用。</span></div>)}<p className="keyboard-note">鼠标快捷操作仅在终端内容区域生效。显式设置的鼠标映射优先于“右键粘贴”开关；默认 Ctrl+C、Ctrl+R 与 tmux 前缀可继续使用，重新映射后以你的设置为准。</p><button className="text-button" onClick={() => { change('shortcuts', { ...defaultSettings.shortcuts }); setRecord(''); setMouseEditor(''); setError(''); }}>恢复默认快捷方式</button></>}
      {tab === 'terminal' && <><h3>输入与鼠标</h3>{([['cursorBlink', '光标闪烁', '关闭后使用稳定的块状光标。'], ['copyOnSelect', '选中即复制', '选中文本后复制到系统剪贴板。'], ['rightClickPaste', '右键粘贴', '未设置显式右键快捷操作时，右键粘贴；显式鼠标映射优先。']] as const).map(([id, title, description]) => <div className="settings-row" key={id}><div><div className="row-title">{title}</div><div className="row-description">{description}</div></div><button role="switch" aria-checked={draft[id]} aria-label={title} className={`switch${draft[id] ? ' checked' : ''}`} onClick={() => change(id, !draft[id])} /></div>)}<div className="form-note">远程命令历史由服务器上的 shell 管理，方向键与 Ctrl+R 可直接使用。终端输出不会另存为命令历史。</div><h3 style={{ marginTop: 25 }}>文件管理</h3><p className="settings-description">本地和远程双栏之间拖动文件即可传输；也可以把资源管理器中的文件拖到远程列表。已有未完成的文件默认尝试断点续传。</p></>}
      {tab === 'about' && <><h3>gooeshell</h3><div className="about-version">图形界面预览版</div><p className="about-copy">面向 Windows 的 SSH 终端与文件管理工具。<br />终端采用 <strong>xterm.js</strong>，连接与文件传输使用 SSH。</p><p className="settings-description">此版本支持真实服务器连接、双栏文件浏览、文件传输、字体和快捷键设置。遇到权限不足时，可以仅为当前操作使用 sudo。</p><p className="settings-description">服务器密码和 sudo 密码不写入连接配置。服务器地址、用户名、私钥路径、指纹选择和外观设置保存在本机。</p></>}
      {error && <div className="form-error" role="alert">{error}</div>}
    </div></div></Modal>;
}

function FilePane({ side, listing, loading, error, selected, connected, load, select, context, open, drop, transferSelected, chooseFolder, chooseUpload }: { side: Side; listing: FileListing; loading: boolean; error: string; selected: string[]; connected: boolean; load: (path: string) => void; select: (entries: string[]) => void; context: (event: React.MouseEvent, entry: FileEntry) => void; open: (entry: FileEntry) => void; drop: (event: React.DragEvent) => void; transferSelected: () => void; chooseFolder?: () => void; chooseUpload?: () => void }) {
  const [collapsed, setCollapsed] = useState(false); const paneName = side === 'local' ? '本地' : '远程';
  const [path, setPath] = useState(listing.path); const [dragging, setDragging] = useState(false); const dragDepth = useRef(0); const anchor = useRef('');
  useEffect(() => setPath(listing.path), [listing.path]);
  const rows = sorted(listing.entries);
  const click = (e: React.MouseEvent, entry: FileEntry) => { if (e.shiftKey && anchor.current) { const a = rows.findIndex(row => row.path === anchor.current), b = rows.findIndex(row => row.path === entry.path); if (a >= 0) { select(rows.slice(Math.min(a, b), Math.max(a, b) + 1).map(row => row.path)); return; } } if (e.ctrlKey || e.metaKey) select(selected.includes(entry.path) ? selected.filter(path => path !== entry.path) : [...selected, entry.path]); else select([entry.path]); anchor.current = entry.path; };
  return <section data-side={side} aria-label={`${paneName}文件管理`} data-collapsed={collapsed} data-drop-label={side === 'remote' ? '松开即可上传到此目录' : '松开即可下载到此目录'} className={`file-pane${dragging ? ' drop-active' : ''}${collapsed ? ' collapsed' : ''}`} onDragEnter={e => { if (collapsed || !connected || (side === 'local' && !e.dataTransfer.types.includes(dragMime))) return; e.preventDefault(); dragDepth.current++; setDragging(true); }} onDragLeave={() => { dragDepth.current--; if (dragDepth.current <= 0) setDragging(false); }} onDragOver={e => { if (!collapsed && connected && (side === 'remote' || e.dataTransfer.types.includes(dragMime))) { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; } }} onDrop={e => { e.preventDefault(); dragDepth.current = 0; setDragging(false); if (!collapsed && connected) drop(e); }}>
    <button type="button" className="file-pane-collapsed-control" title={`展开${paneName}文件栏`} aria-label={`展开${paneName}文件栏`} aria-expanded="false" onClick={() => setCollapsed(false)}>{side === 'local' ? <ChevronRight size={15} /> : <ChevronLeft size={15} />}<span>{paneName}</span><span className="pane-collapsed-count">{selected.length ? `${selected.length} 项已选` : `${listing.entries.length} 项`}</span></button>
    <div className="file-pane-toolbar"><span className={`pane-label ${side === 'remote' ? 'remote' : ''}`}>{side === 'local' ? '▱ 本地' : '▤ 远程'}</span><IconButton title="上一级目录" disabled={!connected || loading} onClick={() => load(parentPath(listing.path, side))}>↑</IconButton><form style={{ display: 'flex', flex: 1, minWidth: 0 }} onSubmit={e => { e.preventDefault(); if (path.trim()) load(path.trim()); }}><input aria-label={side === 'local' ? '本地目录路径' : '远程目录路径'} className="path-input" value={path} onChange={e => setPath(e.target.value)} disabled={!connected} spellCheck={false} placeholder={side === 'remote' ? '连接服务器后浏览文件' : '本地文件路径'} /></form><IconButton title="刷新目录" disabled={!connected || loading} onClick={() => load(listing.path)}>↻</IconButton>{side === 'local' ? <IconButton title="选择本地文件夹" onClick={chooseFolder}>…</IconButton> : <IconButton title="选择文件上传" disabled={!connected} onClick={chooseUpload}>⇧</IconButton>}<button type="button" className="pane-collapse-button" title={`收起${paneName}文件栏`} aria-label={`收起${paneName}文件栏`} aria-expanded="true" onClick={() => setCollapsed(true)}>{side === 'local' ? <ChevronLeft size={14} /> : <ChevronRight size={14} />}</button></div>
    <div className={`file-selection-bar${selected.length ? '' : ' idle'}`} aria-label={`${paneName}文件选择状态`}><span>{selected.length ? `${selected.length} 项已选` : '未选择文件'}</span><span className="toolbar-spacer" /><button disabled={!selected.length || !connected} onClick={transferSelected}>{side === 'local' ? '上传到远程 →' : '← 下载到本地'}</button><button disabled={!selected.length} onClick={() => select([])}>取消</button></div>
    <div className="file-table-wrap">{!connected ? <div className="pane-message"><span>连接服务器后查看远程目录</span><span>支持上传、下载与断点续传</span></div> : loading && rows.length === 0 ? <div className="pane-message"><span className="loading-spin" />正在读取目录…</div> : <table className="file-table"><thead><tr><th>名称</th><th className="size-col">大小</th>{side === 'remote' && <th className="perm-col">权限</th>}<th className="date-col">修改时间</th></tr></thead><tbody>{rows.map(entry => <tr key={entry.path} data-file-path={entry.path} aria-selected={selected.includes(entry.path)} className={selected.includes(entry.path) ? 'selected' : ''} onClick={e => click(e, entry)} onDoubleClick={() => open(entry)} onContextMenu={e => { e.preventDefault(); if (!selected.includes(entry.path)) select([entry.path]); context(e, entry); }} draggable={entry.type !== 'directory'} onDragStart={e => { const paths = selected.includes(entry.path) ? selected : [entry.path]; e.dataTransfer.setData(dragMime, JSON.stringify({ side, paths })); e.dataTransfer.effectAllowed = 'copy'; }}><td className="file-name" title={entry.name}><div className="file-name-inner"><span className={`file-symbol ${entry.type === 'directory' ? 'directory' : entry.name.endsWith('.sh') ? 'script' : ''}`}>{entry.type === 'directory' ? <Folder size={15} strokeWidth={1.6} /> : entry.type === 'symlink' ? <Link2 size={14} /> : entry.name.endsWith('.sh') ? <FileCode2 size={15} strokeWidth={1.6} /> : <FileText size={14} strokeWidth={1.5} />}</span><span>{entry.name}</span></div></td><td className="file-size">{entry.type === 'directory' ? '—' : bytes(entry.size)}</td>{side === 'remote' && <td className="file-perm" title={entry.mode === undefined ? '' : (entry.mode & 0o7777).toString(8)}>{modeText(entry.mode)}</td>}<td className="file-date">{entry.modified ? new Date(entry.modified).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }) : '—'}</td></tr>)}</tbody></table>}{connected && !loading && rows.length === 0 && <div className="pane-message">{error ? '目录读取失败' : '此目录为空'}</div>}</div>{error && <div className="inline-error" title={error}>{error}</div>}<footer className="file-pane-footer"><span>{loading ? '正在刷新…' : `${rows.length} 项`}</span><span>{side === 'local' ? '双击打开 · 拖动文件上传' : '右键更多操作 · 拖入文件上传'}</span></footer>
  </section>;
}

function PermissionsDialog({ entry, apply, close }: { entry: FileEntry; apply: (mode: number) => Promise<void>; close: () => void }) {
  const [mode, setMode] = useState((entry.mode ?? 0o644) & 0o777); const [octal, setOctal] = useState(((entry.mode ?? 0o644) & 0o777).toString(8).padStart(3, '0')); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  return <Modal title="文件权限" compact close={close} footer={<><button className="button secondary" onClick={close}>取消</button><button className="button primary" disabled={busy || !/^[0-7]{3}$/.test(octal)} onClick={async () => { setBusy(true); try { await apply(mode); close(); } catch (e) { setError(errorText(e)); } finally { setBusy(false); } }}>应用权限</button></>}><div className="modal-body"><div className="dialog-path">{entry.path}</div><table className="permission-table"><thead><tr><th>身份</th><th>读取 r</th><th>写入 w</th><th>执行 x</th></tr></thead><tbody>{[['所有者', 6], ['所属组', 3], ['其他人', 0]].map(([name, shift]) => <tr key={name}><td>{name}</td>{[4, 2, 1].map(bit => { const mask = bit << Number(shift); return <td key={bit}><input aria-label={`${name}${{ 4: '读取', 2: '写入', 1: '执行' }[bit]}`} type="checkbox" checked={!!(mode & mask)} onChange={e => { const next = e.target.checked ? mode | mask : mode & ~mask; setMode(next); setOctal(next.toString(8).padStart(3, '0')); }} /></td>; })}</tr>)}</tbody></table><div className="permission-octal"><span>八进制权限</span><input aria-label="八进制权限" value={octal} maxLength={3} inputMode="numeric" pattern="[0-7]{3}" onChange={e => { setOctal(e.target.value); if (/^[0-7]{3}$/.test(e.target.value)) setMode(parseInt(e.target.value, 8)); }} /><span className="mono">{modeText(mode)}</span></div><p className="settings-description" style={{ marginTop: 14 }}>读取：查看内容；写入：修改内容。执行：运行文件，或进入目录。仅修改此项，不递归修改子目录。已有特殊位会保留，此处不能新增或移除特殊位。</p>{((entry.mode || 0) & 0o7000) !== 0 && <div className="form-note">已有特殊位：{[[0o4000, 'setuid'], [0o2000, 'setgid'], [0o1000, 'sticky']].filter(([bit]) => ((entry.mode || 0) & Number(bit)) !== 0).map(([, name]) => name).join('、')}。保存时会保留。</div>}{error && <div className="form-error">{error}</div>}</div></Modal>;
}

function SudoDialog({ task, close, run }: { task: SudoTask; close: () => void; run: (password: string) => Promise<void> }) { const [password, setPassword] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); return <Modal title="为本次操作使用 sudo" compact close={() => { if (!busy) close(); }} footer={<><button className="button secondary" disabled={busy} onClick={close}>取消</button><button form="sudo-form" type="submit" className="button primary" disabled={busy}>{busy ? '正在执行…' : '使用 sudo 执行'}</button></>}><form id="sudo-form" className="modal-body" onSubmit={async e => { e.preventDefault(); setBusy(true); try { await run(password); setPassword(''); close(); } catch (e) { setError(errorText(e)); setPassword(''); } finally { setBusy(false); } }}><p className="sudo-description">当前账号权限不足，或你选择了 sudo 运行。提升权限仅用于下面这一次操作。</p><div className="dialog-path">{task.label}</div><div className="form-field" style={{ marginTop: 17 }}><label htmlFor="sudo-password">服务器 sudo 密码</label><input id="sudo-password" type="password" value={password} autoFocus autoComplete="new-password" onChange={e => setPassword(e.target.value)} placeholder="免密 sudo 可留空" /></div><div className="form-note">不会保存密码，不改变终端身份。服务器必须已允许此账号使用 sudo。</div>{error && <div className="form-error" role="alert">{error}</div>}</form></Modal>; }

export default function App() {
  const [profiles, setProfiles] = useState<HostProfile[]>([]); const [settings, setSettings] = useState<AppSettings>(defaultSettings); const [sessions, setSessions] = useState<SessionInfo[]>([]); const [activeId, setActiveId] = useState(''); const [closed, setClosed] = useState<Record<string, string>>({}); const [version, setVersion] = useState('预览版');
  const [connection, setConnection] = useState<{ profile?: HostProfile } | null>(null); const [connecting, setConnecting] = useState(false); const [connectionError, setConnectionError] = useState(''); const [settingsOpen, setSettingsOpen] = useState(false); const [hostKey, setHostKey] = useState<Extract<AppEvent, { type: 'hostKey' }> | null>(null);
  const [filesVisible, setFilesVisible] = useState(true); const [filesHeight, setFilesHeight] = useState(330); const [zen, setZen] = useState(false); const [sidebarCollapsed, setSidebarCollapsed] = useState(false); const [transfers, setTransfers] = useState<TransferInfo[]>([]); const [queueCollapsed, setQueueCollapsed] = useState(false); const [toasts, setToasts] = useState<Toast[]>([]); const [sudoTask, setSudoTask] = useState<SudoTask | null>(null); const [context, setContext] = useState<Context | null>(null); const [permissions, setPermissions] = useState<FileEntry | null>(null);
  const [local, setLocal] = useState<FileListing>({ path: '', entries: [] }); const [remote, setRemote] = useState<FileListing>({ path: '', entries: [] }); const [loading, setLoading] = useState<Record<Side, boolean>>({ local: false, remote: false }); const [fileErrors, setFileErrors] = useState<Record<Side, string>>({ local: '', remote: '' }); const [selection, setSelection] = useState<Record<Side, string[]>>({ local: [], remote: [] });
  const [editor, setEditor] = useState<{ side: Side; entry: FileEntry; text: string; truncated: boolean } | null>(null); const [editorBusy, setEditorBusy] = useState(false); const [operationDialog, setOperationDialog] = useState<{ type: 'mkdir' | 'rename'; side: Side; entry?: FileEntry; value: string } | null>(null); const [commandOutput, setCommandOutput] = useState<{ title: string; text: string } | null>(null); const [initialError, setInitialError] = useState('');
  const terminalRegion = useRef<HTMLElement>(null);
  const active = sessions.find(session => session.id === activeId); const connected = !!active && !closed[active.id]; const activeRef = useRef(activeId); const listingsRef = useRef({ local, remote }); const transferRequests = useRef(new Map<string, TransferRequest>()); const remotePaths = useRef(new Map<string, string>()); const loadGeneration = useRef<Record<Side, number>>({ local: 0, remote: 0 }); const nextToast = useRef(0);
  activeRef.current = activeId; listingsRef.current = { local, remote };
  const notify = useCallback((message: string, error = false) => { const id = ++nextToast.current; setToasts(prev => [...prev.slice(-3), { id, message, error }]); setTimeout(() => setToasts(prev => prev.filter(toast => toast.id !== id)), error ? 10000 : 5000); }, []);
  const doOperation = useCallback(async (label: string, operation: (elevation: Elevation) => Promise<unknown>, allowElevation = true) => { try { await operation({}); } catch (e) { const message = errorText(e); if (allowElevation && /PERMISSION_DENIED|permission denied|权限不足/i.test(message)) setSudoTask({ label, run: operation }); else notify(message, true); } }, [notify]);
  const loadFiles = useCallback(async (side: Side, path: string, elevation: Elevation = {}) => { const sessionId = activeRef.current; if (side === 'remote' && !sessionId) return; const generation = ++loadGeneration.current[side]; setLoading(prev => ({ ...prev, [side]: true })); setFileErrors(prev => ({ ...prev, [side]: '' })); try { const listing = side === 'local' ? await api.localList(path) : await api.remoteList({ sessionId, path: path || '.', ...elevation }); if (generation !== loadGeneration.current[side] || (side === 'remote' && activeRef.current !== sessionId)) return; (side === 'local' ? setLocal : setRemote)(listing); if (side === 'remote') remotePaths.current.set(sessionId, listing.path); setSelection(prev => ({ ...prev, [side]: [] })); } catch (e) { if (generation !== loadGeneration.current[side] || (side === 'remote' && activeRef.current !== sessionId)) return; const message = errorText(e); setFileErrors(prev => ({ ...prev, [side]: message.replace(/^.*?PERMISSION_DENIED:?\s*/, '') })); if (side === 'remote' && /PERMISSION_DENIED|permission denied|权限不足/i.test(message) && !elevation.elevated) setSudoTask({ label: `读取目录 ${path}`, run: async elevate => { const listing = await api.remoteList({ sessionId, path, ...elevate }); if (activeRef.current === sessionId) { setRemote(listing); remotePaths.current.set(sessionId, listing.path); setFileErrors(prev => ({ ...prev, remote: '' })); } } }); else if (elevation.elevated) throw e; } finally { if (generation === loadGeneration.current[side]) setLoading(prev => ({ ...prev, [side]: false })); } }, []);
  useEffect(() => { let cancelled = false; api.initial().then(state => { if (cancelled) return; setProfiles(state.profiles); setSettings({ ...defaultSettings, ...state.settings, shortcuts: { ...defaultSettings.shortcuts, ...state.settings.shortcuts } }); setVersion(state.version); void loadFiles('local', state.localHome); }).catch(e => { if (!cancelled) setInitialError(errorText(e)); }); return () => { cancelled = true; }; }, [loadFiles]);
  useEffect(() => { setRemote({ path: remotePaths.current.get(activeId) || '', entries: [] }); setSelection(prev => ({ ...prev, remote: [] })); setFileErrors(prev => ({ ...prev, remote: '' })); if (activeId && !closed[activeId]) void loadFiles('remote', remotePaths.current.get(activeId) || '.'); }, [activeId, closed, loadFiles]);
  useEffect(() => api.onEvent(event => { if (event.type === 'hostKey') setHostKey(event); if (event.type === 'notice') notify(event.message); if (event.type === 'sessionClosed') { setClosed(prev => ({ ...prev, [event.sessionId]: event.message || '连接已关闭' })); notify(event.message || '服务器连接已关闭'); } if (event.type === 'transfer') { const transfer = event.transfer; setTransfers(prev => { const i = prev.findIndex(item => item.id === transfer.id); if (i < 0) return [...prev, transfer]; const next = [...prev]; next[i] = transfer; return next; }); if (transfer.state === 'completed') { transferRequests.current.delete(transfer.id); const side = transfer.direction === 'upload' ? 'remote' : 'local'; if (side === 'local' || transfer.sessionId === activeRef.current) void loadFiles(side, listingsRef.current[side].path); } if (transfer.state === 'failed') notify(`${transfer.name}：${transferErrorMessage(transfer.error || '传输失败')}`, true); } }), [loadFiles, notify]);
  useEffect(() => {
    const modalOpen = !!(connection || settingsOpen || sudoTask || hostKey || editor || operationDialog || permissions || commandOutput);
    const findAction = (combo: string) => { const id = Object.entries(settings.shortcuts).find(([, value]) => value.toLowerCase() === combo.toLowerCase())?.[0]; return id && ['connect', 'settings', 'files', 'fullscreen', 'zen'].includes(id) ? id : undefined; };
    const run = (id: string) => { if (id === 'connect') { setConnectionError(''); setConnection({}); } if (id === 'settings') setSettingsOpen(true); if (id === 'files') { if (zen) { setZen(false); setFilesVisible(true); } else setFilesVisible(value => !value); } if (id === 'fullscreen') void api.fullscreen().catch(e => notify(errorText(e), true)); if (id === 'zen') setZen(value => !value); };
    const withinTerminal = (target: EventTarget | null) => target instanceof Element && !!target.closest('.terminal-region .xterm');
    const keyboard = (event: KeyboardEvent) => { if (event.isComposing || modalOpen) return; const id = findAction(keyCombo(event)); if (!id) return; if (!event.ctrlKey && !event.altKey && !event.metaKey && !/^F\d+$/.test(event.key) && !withinTerminal(event.target)) return; event.preventDefault(); event.stopImmediatePropagation(); if (!event.repeat) run(id); };
    const mouse = (event: MouseEvent) => { if (modalOpen || !withinTerminal(event.target)) return; const id = findAction(mouseChord(event)); if (!id) return; event.preventDefault(); event.stopImmediatePropagation(); run(id); };
    const suppressMouseDefault = (event: MouseEvent) => { if (withinTerminal(event.target) && findAction(mouseChord(event))) { event.preventDefault(); event.stopImmediatePropagation(); } };
    const region = terminalRegion.current; window.addEventListener('keydown', keyboard, true); region?.addEventListener('mousedown', mouse, true); region?.addEventListener('contextmenu', suppressMouseDefault, true); region?.addEventListener('auxclick', suppressMouseDefault, true);
    return () => { window.removeEventListener('keydown', keyboard, true); region?.removeEventListener('mousedown', mouse, true); region?.removeEventListener('contextmenu', suppressMouseDefault, true); region?.removeEventListener('auxclick', suppressMouseDefault, true); };
  }, [settings.shortcuts, connection, settingsOpen, sudoTask, hostKey, editor, operationDialog, permissions, commandOutput, notify, zen]);
  useEffect(() => { if (!context) return; const dismiss = () => setContext(null); window.addEventListener('click', dismiss); window.addEventListener('blur', dismiss); return () => { window.removeEventListener('click', dismiss); window.removeEventListener('blur', dismiss); }; }, [context]);
  useEffect(() => { if (filesVisible) return; setContext(null); const frame = requestAnimationFrame(() => { const activeWrapper = terminalRegion.current?.querySelector<HTMLElement>('[data-terminal-session][data-active="true"]'); activeWrapper?.querySelector<HTMLTextAreaElement>('.xterm-helper-textarea')?.focus({ preventScroll: true }); }); return () => cancelAnimationFrame(frame); }, [filesVisible, activeId]);
  const saveProfile = async (profile: HostProfile) => { await api.saveProfile(profile); setProfiles(prev => [...prev.filter(item => item.id !== profile.id), profile]); };
  const connect = async (profile: HostProfile, password: string, passphrase: string) => { setConnecting(true); setConnectionError(''); try { await saveProfile(profile); const session = await api.connect({ profile, password: profile.auth === 'password' ? password : undefined, passphrase: profile.auth === 'key' ? passphrase : undefined }); setSessions(prev => [...prev, session]); setActiveId(session.id); setConnection(null); notify(isPreview ? '已打开演示会话，没有连接真实服务器' : `已连接 ${profile.name}`); } catch (e) { setConnectionError(errorText(e)); } finally { setConnecting(false); } };
  const closeSession = async (id: string) => { try { await api.disconnect(id); } catch (e) { notify(errorText(e), true); } setSessions(prev => { const next = prev.filter(item => item.id !== id); if (activeRef.current === id) setActiveId(next.at(-1)?.id || ''); return next; }); remotePaths.current.delete(id); };
  const queueTransfer = async (request: TransferRequest) => { const safeRequest: TransferRequest = { sessionId: request.sessionId, direction: request.direction, source: request.source, destinationDir: request.destinationDir, resume: true }; try { const id = await api.transfer(safeRequest); transferRequests.current.set(id, safeRequest); } catch (error) { notify(transferErrorMessage(errorText(error)), true); } };
  const startTransfer = async (side: Side, paths: string[]) => { const sessionId = activeRef.current; if (!sessionId || closed[sessionId]) { notify('请先连接服务器。', true); return; } const target = side === 'local' ? listingsRef.current.remote.path : listingsRef.current.local.path; for (const source of paths) await queueTransfer({ sessionId, direction: side === 'local' ? 'upload' : 'download', source, destinationDir: target, resume: true }); };
  const retryTransfer = async (transfer: TransferInfo) => { const request = transferRequests.current.get(transfer.id) || { sessionId: transfer.sessionId, direction: transfer.direction, source: transfer.source, destinationDir: parentPath(transfer.destination, transfer.direction === 'upload' ? 'remote' : 'local'), resume: true }; await queueTransfer(request); };
  const transferSelected = (side: Side) => { const entries = listingsRef.current[side].entries.filter(entry => selection[side].includes(entry.path)); const files = entries.filter(entry => entry.type !== 'directory'); if (entries.some(entry => entry.type === 'directory')) notify('目录传输尚未提供，请先进入目录选择文件。'); if (files.length) void startTransfer(side, files.map(entry => entry.path)); };
  const receiveDrop = (side: Side, event: React.DragEvent) => { const data = event.dataTransfer.getData(dragMime); if (data) { try { const payload = JSON.parse(data) as { side: Side; paths: string[] }; if (payload.side === side) return; if (!['local', 'remote'].includes(payload.side) || !Array.isArray(payload.paths)) return; void startTransfer(payload.side, payload.paths); } catch { notify('无法读取拖动的文件。', true); } } else if (side === 'remote') { const paths = Array.from(event.dataTransfer.files).map(file => api.pathForFile(file)).filter(Boolean); if (paths.length) void startTransfer('local', paths); } };
  const remoteRequest = (path: string, elevation: Elevation = {}): RemoteRequest => ({ sessionId: activeId, path, ...elevation });
  const openFile = (side: Side, entry: FileEntry) => { if (entry.type === 'directory') { void loadFiles(side, entry.path); return; } void doOperation(`读取 ${entry.name}`, async elevation => { const file = await api.readFile({ ...remoteRequest(entry.path, elevation), side }); setEditor({ side, entry, text: file.text, truncated: file.truncated }); }, side === 'remote'); };
  const runFile = (entry: FileEntry, executable: boolean, sudo: boolean) => { const operation = async (elevation: Elevation) => { const result = await api.runFile({ ...remoteRequest(entry.path, elevation), makeExecutable: executable }); setCommandOutput({ title: `${entry.name} · 退出码 ${result.exitCode}`, text: result.output || '命令已完成，没有输出。' }); if (executable) void loadFiles('remote', remote.path); }; if (sudo) setSudoTask({ label: `sudo 运行 ${entry.path}`, run: operation }); else void doOperation(`运行 ${entry.path}`, operation); };
  const resizeFiles = (e: React.PointerEvent) => { e.preventDefault(); const startY = e.clientY, startHeight = filesHeight; const move = (event: PointerEvent) => setFilesHeight(Math.min(window.innerHeight - 190, Math.max(170, startHeight + startY - event.clientY))); const stop = () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', stop); document.body.style.cursor = ''; document.body.style.userSelect = ''; }; document.body.style.cursor = 'row-resize'; document.body.style.userSelect = 'none'; window.addEventListener('pointermove', move); window.addEventListener('pointerup', stop); };
  const activeTransfers = transfers.filter(transfer => ['queued', 'checking', 'transferring'].includes(transfer.state));
  const showConnection = (profile?: HostProfile) => { setConnectionError(''); setConnection({ profile }); };
  return <div className={`app-shell${zen ? ' zen' : ''}`}>
    <aside className={`sidebar${sidebarCollapsed ? ' collapsed' : ''}`}><div className="brand"><img className="brand-mark" src={appIcon} alt="" aria-hidden="true" draggable={false} /><span>gooeshell</span><small>PREVIEW</small></div><div className="sidebar-actions"><button className="button primary" title="新建连接" onClick={() => showConnection()}>{sidebarCollapsed ? '+' : '+　新建连接'}</button></div><div className="sidebar-heading"><span>我的服务器</span><span>{profiles.length}</span></div><nav className="hosts">{profiles.length ? profiles.map(profile => { const session = sessions.find(item => item.profile.id === profile.id && !closed[item.id]); return <button key={profile.id} className={`host${active?.profile.id === profile.id ? ' active' : ''}`} title={`${profile.name}\n${profile.username}@${profile.host}:${profile.port}\n双击打开连接设置`} onClick={() => session ? setActiveId(session.id) : showConnection(profile)} onDoubleClick={() => showConnection(profile)}><span className="host-icon"><Server size={17} strokeWidth={1.6} /></span><span className="host-copy"><span className="host-name">{profile.name}</span><span className="host-address">{profile.username}@{profile.host}</span></span>{session && <span className="host-dot" />}</button>; }) : <div className="sidebar-empty">尚未添加服务器。<br />点击上方“新建连接”开始。</div>}</nav><div className="sidebar-bottom"><button onClick={() => setSidebarCollapsed(value => !value)} title="折叠侧栏"><span>{sidebarCollapsed ? '»' : '«'}</span><span className="item-label">折叠侧栏</span></button><button onClick={() => setSettingsOpen(true)} title="设置"><span>⚙</span><span className="item-label">设置</span><kbd>{shortcutLabel(settings.shortcuts.settings)}</kbd></button></div></aside>
    <main className="workspace"><header className="titlebar"><span className="workspace-title">{active?.profile.name || '工作空间'}</span>{active && <span className="breadcrumb">{active.profile.username}@{active.profile.host}:{active.profile.port}</span>}<span className="toolbar-spacer" /><span className={`connection-state ${connected ? 'connected' : connecting ? 'connecting' : ''}`}><i />{isPreview ? '浏览器演示 · 无真实连接' : connected ? '已连接' : connecting ? '连接中' : active ? '已断开' : '就绪'}</span><span className="toolbar-divider" /><button type="button" className={`files-toggle${filesVisible ? ' active' : ''}`} aria-label={filesVisible ? '收起文件管理' : '展开文件管理'} aria-expanded={filesVisible} aria-controls="file-manager" title={`${filesVisible ? '收起文件管理' : '展开文件管理'} · ${shortcutLabel(settings.shortcuts.files)}${activeTransfers.length ? ` · ${activeTransfers.length} 个传输任务进行中` : ''}`} onClick={() => setFilesVisible(value => !value)}><PanelBottom size={15} strokeWidth={1.7} /><span>{filesVisible ? '收起文件管理' : '展开文件管理'}</span>{activeTransfers.length > 0 && <span className="files-transfer-count" aria-label={`${activeTransfers.length} 个传输任务进行中`}>{activeTransfers.length}</span>}</button><IconButton title={`纯终端模式 · ${shortcutLabel(settings.shortcuts.zen)}`} onClick={() => setZen(true)}>⛶</IconButton><IconButton title="设置" onClick={() => setSettingsOpen(true)}>⚙</IconButton>{!isPreview && <div className="window-controls"><button type="button" title="最小化" aria-label="最小化窗口" onClick={() => api.minimize()}><Minus size={14} strokeWidth={1.3} /></button><button type="button" title="最大化 / 还原" aria-label="最大化或还原窗口" onClick={() => api.maximize()}><Square size={12} strokeWidth={1.2} /></button><button type="button" className="window-close" title="关闭窗口" aria-label="关闭窗口" onClick={() => api.closeWindow()}><X size={16} strokeWidth={1.3} /></button></div>}</header>
    <div className="tabbar">{sessions.map(session => <div role="tab" tabIndex={0} aria-selected={session.id === activeId} key={session.id} className={`terminal-tab${session.id === activeId ? ' active' : ''}`} onClick={() => setActiveId(session.id)} onKeyDown={e => { if (e.key === 'Enter') setActiveId(session.id); }}><span style={{ color: closed[session.id] ? '#8a5965' : '#61bba1' }}>●</span><span>{session.profile.name}</span><button className="tab-close" title="关闭连接" onClick={e => { e.stopPropagation(); void closeSession(session.id); }}>×</button></div>)}<IconButton title="新建连接" onClick={() => showConnection()}>+</IconButton></div>
    <section className="terminal-region" ref={terminalRegion}>{sessions.map(session => <div className={`terminal-instance${session.id !== activeId ? ' hidden' : ''}`} key={session.id} data-terminal-session={session.id} data-active={session.id === activeId}><TerminalView session={session} settings={settings} active={session.id === activeId} onFontSizeChange={size => { const next = { ...settings, fontSize: size }; setSettings(next); void api.saveSettings(next).catch(e => notify(errorText(e), true)); }} /></div>)}{!active && <div className="empty-terminal"><img className="empty-app-icon" src={appIcon} alt="gooeshell" draggable={false} /><h1>连接，开始工作。</h1><p>SSH 终端与文件管理，在一个窗口中。<br />选择左侧服务器，或添加一个新连接。</p><div className="empty-actions"><button className="button primary" onClick={() => showConnection()}>+ 新建 SSH 连接</button><button className="button secondary" onClick={() => setSettingsOpen(true)}>字体与快捷键</button></div><span className="shortcut-hint">{shortcutLabel(settings.shortcuts.connect)} 新建连接　·　F11 全屏</span>{!window.gooeshell && <span className="form-note warning">浏览器演示模式 · 真实 SSH 连接请使用桌面程序</span>}{initialError && <div className="form-error">{initialError}</div>}</div>}</section><button className="zen-exit" onClick={() => setZen(false)}>退出纯终端 · {shortcutLabel(settings.shortcuts.zen)}</button>
    <><div className="splitter" hidden={!filesVisible} role="separator" aria-label="调整文件管理高度" aria-orientation="horizontal" onPointerDown={resizeFiles} /><section id="file-manager" className="files-area" hidden={!filesVisible} style={{ height: filesHeight }}><div className="files-section-bar"><span>文件管理</span><span className="muted">本地 ⇄ 远程</span><span className="toolbar-spacer" /><button className="text-button" onClick={() => setOperationDialog({ type: 'mkdir', side: 'local', value: '' })}>本地新建文件夹</button><span className="muted">·</span><button className="text-button" disabled={!connected} onClick={() => setOperationDialog({ type: 'mkdir', side: 'remote', value: '' })}>远程新建文件夹</button><button type="button" className="files-collapse" title="收起文件管理" aria-label="收起文件管理" onClick={() => setFilesVisible(false)}><ChevronDown size={14} /><span>收起</span></button></div><div className="dual-files">{(['local', 'remote'] as const).map(side => <FilePane key={side} side={side} listing={side === 'local' ? local : remote} loading={loading[side]} error={fileErrors[side]} selected={selection[side]} connected={side === 'local' || connected} load={path => void loadFiles(side, path)} select={paths => setSelection(prev => ({ ...prev, [side]: paths }))} context={(event, entry) => setContext({ x: Math.min(event.clientX, window.innerWidth - 245), y: Math.min(event.clientY, window.innerHeight - 310), side, entry })} open={entry => openFile(side, entry)} drop={event => receiveDrop(side, event)} transferSelected={() => transferSelected(side)} chooseFolder={async () => { try { const [path] = await api.chooseFiles({ directory: true, title: '选择本地目录' }); if (path) void loadFiles('local', path); } catch (e) { notify(errorText(e), true); } }} chooseUpload={async () => { try { const paths = await api.chooseFiles({ multiple: true, title: '选择上传文件' }); if (paths.length) void startTransfer('local', paths); } catch (e) { notify(errorText(e), true); } }} />)}</div><section className={`transfer-area${queueCollapsed ? ' queue-collapsed' : ''}`}><div className="transfer-header"><span>传输队列</span><span className="badge">{activeTransfers.length}</span><span className="muted">{activeTransfers.length ? '传输中' : '空闲'}</span><span className="toolbar-spacer" /><button className="text-button" style={{ fontSize: 10 }} onClick={() => setTransfers(prev => prev.filter(item => !['completed', 'cancelled'].includes(item.state)))}>清除已完成</button><button type="button" className="transfer-toggle" title={queueCollapsed ? '展开传输队列' : '收起传输队列'} aria-label={queueCollapsed ? '展开传输队列' : '收起传输队列'} aria-expanded={!queueCollapsed} aria-controls="transfer-queue-body" onClick={() => setQueueCollapsed(value => !value)}>{queueCollapsed ? <ChevronUp size={13} /> : <ChevronDown size={13} />}<span>{queueCollapsed ? '展开' : '收起'}</span></button></div><div id="transfer-queue-body" className="transfer-list" hidden={queueCollapsed}>{transfers.length === 0 ? <div className="transfer-empty">拖动文件到另一栏，或右键选择上传 / 下载。传输任务在这里显示。</div> : transfers.map(transfer => <div className="transfer-row" key={transfer.id} title={transfer.error || `${transfer.source} → ${transfer.destination}`}><span className="transfer-direction">{transfer.direction === 'upload' ? '↑' : '↓'}</span><span className="transfer-name">{transfer.name}</span><span className="transfer-detail">{bytes(transfer.done)} / {bytes(transfer.total)}</span><div className="transfer-progress"><span style={{ width: `${transfer.total ? Math.min(100, transfer.done / transfer.total * 100) : transfer.state === 'completed' ? 100 : 0}%` }} /></div><span className={`transfer-status ${transfer.state}`}>{({ queued: '等待中', checking: '校验中', transferring: '传输中', completed: '已完成', cancelled: '已取消', failed: '失败' })[transfer.state]}</span>{['queued', 'checking', 'transferring'].includes(transfer.state) ? <IconButton title="取消传输" onClick={() => void api.cancelTransfer(transfer.id).catch(e => notify(errorText(e), true))}>×</IconButton> : transfer.state === 'failed' || transfer.state === 'cancelled' ? <IconButton title="继续传输" onClick={() => { void retryTransfer(transfer); }}>↻</IconButton> : <span style={{ width: 23 }} />}</div>)}</div></section></section></>
    <footer className="statusbar"><span className="status-product">gooeshell</span><span className="status-note">{active ? closed[active.id] || `${active.profile.username}@${active.profile.host}` : isPreview ? '浏览器演示 · 未连接服务器' : '就绪'} </span>{active && <button onClick={() => showConnection(active.profile)}>{closed[active.id] ? '重新连接' : '连接设置'}</button>}<span className="status-right">{active?.profile.encoding.toUpperCase() || 'UTF-8'}　·　{settings.fontSize}px　·　{version}</span></footer></main>
    {connection && <ConnectionDialog key={connection.profile?.id || 'new'} profile={connection.profile} busy={connecting} error={connectionError} onSave={saveProfile} onConnect={connect} close={() => setConnection(null)} />}
    {settingsOpen && <SettingsDialog settings={settings} save={async value => { await api.saveSettings(value); setSettings(value); notify('设置已保存'); }} close={() => setSettingsOpen(false)} />}
    {editor && <Modal title={`${editor.entry.name} · ${editor.side === 'local' ? '本地' : '远程'}文本编辑`} wide close={() => setEditor(null)} footer={<><span className="footer-note">{editor.truncated ? '内容已截断，仅供预览，无法保存' : '文本以 UTF-8 读写'}</span><button className="button secondary" onClick={() => setEditor(null)}>关闭</button><button className="button primary" disabled={editorBusy || editor.truncated} onClick={() => { const current = editor; void doOperation(`保存 ${current.entry.path}`, async elevation => { setEditorBusy(true); try { await api.writeFile({ ...remoteRequest(current.entry.path, elevation), side: current.side, text: current.text }); notify('文件已保存'); void loadFiles(current.side, listingsRef.current[current.side].path); } finally { setEditorBusy(false); } }, current.side === 'remote'); }}>保存文件</button></>}><div className="modal-body"><div className="dialog-path" style={{ marginBottom: 10 }}>{editor.entry.path}</div><textarea aria-label="文件内容" value={editor.text} readOnly={editor.truncated} onChange={e => setEditor({ ...editor, text: e.target.value })} spellCheck={false} style={{ fontFamily: 'var(--mono)', height: '42vh', resize: 'vertical', lineHeight: 1.6 }} /></div></Modal>}
    {operationDialog && <Modal title={operationDialog.type === 'mkdir' ? '新建文件夹' : '重命名'} compact close={() => setOperationDialog(null)} footer={<><button className="button secondary" onClick={() => setOperationDialog(null)}>取消</button><button className="button primary" form="file-name-form" type="submit" disabled={!operationDialog.value.trim() || /[\\/]/.test(operationDialog.value)}>确定</button></>}><form id="file-name-form" className="modal-body" onSubmit={e => { e.preventDefault(); const dialog = operationDialog; if (!dialog.value.trim() || /[\\/]/.test(dialog.value) || ['.', '..'].includes(dialog.value.trim())) return; void doOperation(`${dialog.type === 'mkdir' ? '新建' : '重命名'} ${dialog.value}`, async elevation => { if (dialog.type === 'mkdir') await api.mkdir({ ...remoteRequest(joinPath(listingsRef.current[dialog.side].path, dialog.value, dialog.side), elevation), side: dialog.side }); else if (dialog.entry) await api.rename({ ...remoteRequest(dialog.entry.path, elevation), side: dialog.side, destination: joinPath(listingsRef.current[dialog.side].path, dialog.value, dialog.side) }); setOperationDialog(null); void loadFiles(dialog.side, listingsRef.current[dialog.side].path); }, dialog.side === 'remote'); }}><div className="form-field"><label htmlFor="file-new-name">{operationDialog.side === 'remote' ? '远程' : '本地'}名称</label><input id="file-new-name" autoFocus value={operationDialog.value} onChange={e => setOperationDialog({ ...operationDialog, value: e.target.value })} /></div></form></Modal>}
    {permissions && <PermissionsDialog entry={permissions} close={() => setPermissions(null)} apply={async mode => { const entry = permissions; await doOperation(`修改权限 ${entry.path} → ${mode.toString(8)}`, async elevation => { await api.chmod({ ...remoteRequest(entry.path, elevation), mode }); notify('权限已更新'); void loadFiles('remote', remote.path); }); }} />}
    {commandOutput && <Modal title={commandOutput.title} wide close={() => setCommandOutput(null)} footer={<button className="button primary" onClick={() => setCommandOutput(null)}>关闭</button>}><div className="modal-body"><textarea aria-label="命令执行结果" value={commandOutput.text} readOnly spellCheck={false} style={{ fontFamily: 'var(--mono)', height: '40vh', lineHeight: 1.6 }} /></div></Modal>}
    {sudoTask && <SudoDialog task={sudoTask} close={() => setSudoTask(null)} run={async password => { await sudoTask.run({ elevated: true, sudoPassword: password }); notify('操作已提交'); }} />}
    {hostKey && <Modal title={hostKey.previousFingerprint ? '服务器指纹发生变化' : '确认服务器身份'} compact close={() => { void api.confirmHostKey(hostKey.requestId, 'reject'); setHostKey(null); }} footer={<><button className="button secondary" onClick={() => { void api.confirmHostKey(hostKey.requestId, 'reject'); setHostKey(null); }}>取消连接</button><button className="button secondary" onClick={() => { void api.confirmHostKey(hostKey.requestId, 'once'); setHostKey(null); }}>仅信任本次</button>{hostKey.saveAllowed !== false && <button className="button primary" onClick={() => { void api.confirmHostKey(hostKey.requestId, 'save'); setHostKey(null); }}>信任并保存</button>}</>}><div className="modal-body"><p className="sudo-description">{hostKey.host}:{hostKey.port}</p><p className="settings-description">请核对服务器提供的 SSH 指纹。</p><div className="trust-fingerprint">{hostKey.fingerprint}</div>{hostKey.previousFingerprint && <><p className="file-operation-warning">此指纹与上次记录不一致。请先确认服务器是否更换过密钥。</p><div className="trust-fingerprint" style={{ color: '#c9a88a' }}>上次：{hostKey.previousFingerprint}</div></>}</div></Modal>}
    {context && <div className="context-menu" style={{ left: context.x, top: Math.max(5, context.y) }} onClick={e => e.stopPropagation()}><div className="menu-caption">{context.entry.name}</div><button onClick={() => { openFile(context.side, context.entry); setContext(null); }}>{context.entry.type === 'directory' ? '打开目录' : '预览 / 编辑文本'}</button>{context.entry.type !== 'directory' && <button disabled={!connected} onClick={() => { transferSelected(context.side); setContext(null); }}>{context.side === 'local' ? '上传到远程目录' : '下载到本地目录'}<span className="menu-end">{context.side === 'local' ? '→' : '←'}</span></button>}<button onClick={() => { setOperationDialog({ type: 'rename', side: context.side, entry: context.entry, value: context.entry.name }); setContext(null); }}>重命名</button>{context.side === 'local' && <button onClick={() => { void api.showInFolder(context.entry.path).catch(e => notify(errorText(e), true)); setContext(null); }}>在资源管理器中显示</button>}{context.side === 'remote' && <><hr /><button onClick={() => { setPermissions(context.entry); setContext(null); }}>权限与属性<span className="menu-end">rwx</span></button>{context.entry.name.endsWith('.sh') && context.entry.type !== 'directory' && <><hr /><button onClick={() => { runFile(context.entry, false, false); setContext(null); }}>运行脚本</button><button onClick={() => { runFile(context.entry, true, false); setContext(null); }}>赋予执行权限并运行</button><button onClick={() => { runFile(context.entry, false, true); setContext(null); }}>使用 sudo 运行…</button></>}</>}</div>}
    <div className="toast-stack" aria-live="polite">{toasts.map(toast => <div key={toast.id} className={`toast${toast.error ? ' error' : ''}`}><button title="关闭提示" onClick={() => setToasts(prev => prev.filter(item => item.id !== toast.id))}>×</button>{toast.message}</div>)}</div>
  </div>;
}
